package accounts

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"

	"github.com/duxlabs-dev/dux-calendar/core/ent/account"
	"github.com/duxlabs-dev/dux-calendar/core/internal/paths"
	"github.com/duxlabs-dev/dux-calendar/core/internal/providers/external"
	"github.com/duxlabs-dev/dux-calendar/core/repo"
)

// ExternalManifestName is the file, in the config dir, listing declaratively
// managed external accounts (e.g. generated by the Home Manager module).
const ExternalManifestName = "external-accounts.json"

const (
	externalIDPrefix = "external:"
	settingManaged   = "managed"
)

var externalNameRE = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)

type ExternalInput struct {
	// Name is the short, stable identifier; the account id is "external:<name>".
	Name        string            `json:"name"`
	DisplayName string            `json:"displayName"`
	Command     []string          `json:"command"`
	Env         map[string]string `json:"env,omitempty"`
}

type externalManifest struct {
	Accounts []ExternalInput `json:"accounts"`
}

func ExternalAccountID(name string) string { return externalIDPrefix + name }

func (in ExternalInput) validate() error {
	switch {
	case !externalNameRE.MatchString(in.Name):
		return fmt.Errorf("external account name %q must match %s", in.Name, externalNameRE)
	case len(ExternalAccountID(in.Name)) > maxAccountIDLen:
		return fmt.Errorf("external account name %q is too long", in.Name)
	case len(in.Command) == 0 || in.Command[0] == "":
		return fmt.Errorf("external account %q: command is required", in.Name)
	}
	return nil
}

func (in ExternalInput) settings(managed bool) map[string]any {
	command := make([]any, len(in.Command))
	for i, arg := range in.Command {
		command[i] = arg
	}
	s := map[string]any{external.SettingCommand: command}
	if len(in.Env) > 0 {
		env := make(map[string]any, len(in.Env))
		for k, v := range in.Env {
			env[k] = v
		}
		s[external.SettingEnv] = env
	}
	if managed {
		s[settingManaged] = true
	}
	return s
}

// AddExternal creates or updates an external account. Accounts added this way
// are never touched by manifest reconciliation.
func AddExternal(ctx context.Context, r *repo.Repo, in ExternalInput) (Result, error) {
	return upsertExternal(ctx, r, in, false)
}

func upsertExternal(ctx context.Context, r *repo.Repo, in ExternalInput, managed bool) (Result, error) {
	in.DisplayName = strings.TrimSpace(in.DisplayName)
	if in.DisplayName == "" {
		in.DisplayName = in.Name
	}
	if err := in.validate(); err != nil {
		return Result{}, err
	}

	id := ExternalAccountID(in.Name)
	settings := in.settings(managed)
	existing, err := r.GetAccount(ctx, id)
	switch {
	case repo.IsNotFound(err):
		if _, err := r.CreateAccount(ctx, repo.CreateAccountInput{
			ID:          id,
			Kind:        account.KindExternal,
			DisplayName: in.DisplayName,
			Settings:    settings,
		}); err != nil {
			return Result{}, err
		}
	case err != nil:
		return Result{}, err
	case existing.Kind != account.KindExternal:
		return Result{}, fmt.Errorf("account %q already exists with kind %s", id, existing.Kind)
	case existing.DisplayName != in.DisplayName || !sameSettings(existing.Settings, settings):
		if _, err := r.UpdateAccount(ctx, id, repo.UpdateAccountInput{
			DisplayName: &in.DisplayName,
			Settings:    settings,
		}); err != nil {
			return Result{}, err
		}
	}
	return Result{AccountID: id, DisplayName: in.DisplayName}, nil
}

// sameSettings compares through a JSON round trip, since stored settings come
// back with JSON-decoded types.
func sameSettings(a, b map[string]any) bool {
	ja, errA := json.Marshal(a)
	jb, errB := json.Marshal(b)
	if errA != nil || errB != nil {
		return false
	}
	var na, nb any
	_ = json.Unmarshal(ja, &na)
	_ = json.Unmarshal(jb, &nb)
	return reflect.DeepEqual(na, nb)
}

// ReconcileExternal makes the managed external accounts match specs exactly:
// declared accounts are created or updated, and previously managed accounts
// that are no longer declared are removed with their synced data.
func ReconcileExternal(ctx context.Context, r *repo.Repo, specs []ExternalInput) error {
	declared := make(map[string]bool, len(specs))
	var errs []error
	for _, spec := range specs {
		res, err := upsertExternal(ctx, r, spec, true)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		declared[res.AccountID] = true
	}

	existing, err := r.ListAccountsByKind(ctx, account.KindExternal)
	if err != nil {
		return errors.Join(append(errs, err)...)
	}
	for _, acc := range existing {
		if managed, _ := acc.Settings[settingManaged].(bool); !managed || declared[acc.ID] {
			continue
		}
		if err := r.DeleteAccount(ctx, acc.ID); err != nil {
			errs = append(errs, fmt.Errorf("remove undeclared account %q: %w", acc.ID, err))
		}
	}
	return errors.Join(errs...)
}

// LoadExternalManifest reads the managed account list. A missing file
// declares no accounts.
func LoadExternalManifest(path string) ([]ExternalInput, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var m externalManifest
	if err := json.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	return m.Accounts, nil
}

func ExternalManifestPath() (string, error) {
	dir, err := paths.ConfigDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, ExternalManifestName), nil
}

// ReconcileExternalManifest applies the manifest in the config dir.
func ReconcileExternalManifest(ctx context.Context, r *repo.Repo) error {
	path, err := ExternalManifestPath()
	if err != nil {
		return err
	}
	specs, err := LoadExternalManifest(path)
	if err != nil {
		return err
	}
	return ReconcileExternal(ctx, r, specs)
}
